{
  "passageId": "sf-film-society",
  "items": [
    {
      "id": "R1",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "장르의 유행과 관습 변화는 영화가 대중의 취향에 반응한다는 일반적 설명을 보여 주는 구체적 사례이다."
    },
    {
      "id": "R2",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "영화에 반영되는 대상을 대중의 취향에서 공유 이념으로 넓히며 논의를 전개한다."
    },
    {
      "id": "R3",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "영화에 이념이 반영되지만 그것이 투명하게 드러나는 것은 아니라는 한계를 제시한다."
    },
    {
      "id": "R4",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "서로 다른 대상의 대조가 아니라 하나의 매체가 드러내면서 동시에 숨긴다는 양면성을 제시한다."
    },
    {
      "id": "R5",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "영화가 숨기는 매체라는 설명을 감추어지는 이념의 구체적인 성격으로 풀어 준다."
    },
    {
      "id": "R6",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "이념이 영화의 이면에 감추어져 있다는 한계에 대응하여 표면의 모티브와 이미지를 해석하는 방법을 제시한다."
    },
    {
      "id": "R7",
      "type": "PROCESS",
      "otherName": "",
      "reason": "숨겨진 이념을 읽어 낸 결과를 바탕으로 사회 이해라는 다음 단계가 진행된다."
    },
    {
      "id": "R8",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "이미지를 해석하여 숨겨진 이념과 사회를 파악한다는 원리를 1920년대 독일 영화라는 구체적 사례에 적용한다."
    },
    {
      "id": "R9",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "앞에서 설명한 크라카우어의 해석 방법과 목적을 사회의 심층적 이해라는 표현으로 다시 진술한다."
    },
    {
      "id": "R10",
      "type": "VIEW_DIFFERENCE",
      "otherName": "",
      "reason": "사회 이해의 통로와 지향점을 두고 크라카우어와 제임슨의 서로 다른 관점을 공격 없이 나란히 제시한다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "현대 사회의 분산성과 파편성을 근거로 그 총체적인 양상을 역사가 된 이후에야 파악할 수 있다고 설명한다."
    },
    {
      "id": "R12",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "역사가 된 사회는 총체적으로 파악할 수 있다는 설명에서 현재도 역사처럼 조망하면 총체를 파악할 수 있다는 판단을 도출한다."
    },
    {
      "id": "R13",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "사건을 완료된 과거처럼 회고적으로 서술한다는 서사의 특성을 근거로 총체적 조망의 가능성을 설명한다."
    },
    {
      "id": "R14",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "서사를 통한 역사화는 현재를 역사처럼 조망하여 사회의 총체적인 양상을 파악하기 위한 수단이다."
    },
    {
      "id": "R15",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "역사화가 적용되는 장르로 SF를 언급한 뒤 SF 자체의 정의와 성립 기준을 설명하는 논의로 옮겨 간다."
    },
    {
      "id": "R16",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 과학 지식에 기반한다는 특성을 인정하면서도 모든 내용의 과학적 사실성까지 요구하지는 않는다는 한계를 밝힌다."
    },
    {
      "id": "R17",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "SF에서 중시하는 개연성이 무엇을 뜻하는지 합리적 납득 가능성으로 풀이한다."
    },
    {
      "id": "R18",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "SF의 장르적 특징인 경이로움을 장대하고 압도적인 대상들이 선사하는 느낌으로 구체화한다."
    },
    {
      "id": "R19",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "SF에서 경이로움을 안겨 주는 대상을 노붐이라고 명명하고 그 이름의 뜻을 풀이한다."
    },
    {
      "id": "R20",
      "type": "OTHER",
      "otherName": "부정·정정",
      "reason": "노붐의 일회적 장치라는 성격을 부정하고 지배적 요소라는 성격으로 바로잡는 관계로, 양면성을 인정하는 양보나 별개 대상의 대조는 아니다."
    },
    {
      "id": "R21",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "작품 전반에 영향을 미치는 지배력은 노붐을 진정한 주인공이라고 평가하는 근거이다."
    },
    {
      "id": "R22",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "현실 세계와 허구적 세계의 차이를 드러내는 핵심성은 노붐을 진정한 주인공이라고 평가하는 근거이다."
    },
    {
      "id": "R23",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "작품의 세계관을 드러내는 기능은 노붐을 진정한 주인공이라고 평가하는 근거이다."
    },
    {
      "id": "R24",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "노붐이 드러내는 현실과 허구의 차이에서 그 다름이 유발하는 낯섦으로 논의를 이어 간다."
    },
    {
      "id": "R25",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "SF가 미래를 상상하지만 그 상상의 기반은 작품이 생산된 시대라는 한 대상 안의 양면성을 제시한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "미래에 대한 상상이 작품의 생산 시대에 기반한다는 사실을 근거로 SF가 현실의 반영이라고 판단한다."
    },
    {
      "id": "R27",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "SF가 당대 현실에 기반한 미래의 상상이라는 설명으로부터 인물과 설정이 현실과 유사하면서도 다르다는 성격을 도출한다."
    },
    {
      "id": "R28",
      "type": "CAUSE",
      "otherName": "",
      "reason": "SF 세계와 현실의 다름이 친숙한 대상을 낯설고 새롭게 느끼게 하는 심리적 작용을 일으킨다."
    },
    {
      "id": "R29",
      "type": "OTHER",
      "otherName": "병렬",
      "reason": "현실에 거리 두기와 비판적으로 바라보기는 다름의 인지에서 함께 나타나는 반응으로 제시되며 둘 사이의 별도 인과나 순서는 명시되지 않는다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "현실과 다른 SF 세계에서 경험하는 낯섦이 현실에 대한 거리 두기와 비판적 성찰로 이어지는 작용을 설명한다."
    },
    {
      "id": "R31",
      "type": "VIEW_AGREEMENT",
      "otherName": "",
      "reason": "크라카우어와 수빈은 각각 영화와 SF가 생산 당시의 사회나 현실을 반영한다는 관점을 공유한다."
    },
    {
      "id": "R32",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "미지의 세계에 대한 동경을 충족해 온 허구적 이야기의 구체적 사례로 유토피아 이야기를 제시한다."
    },
    {
      "id": "R33",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유토피아 이야기와 SF의 유사성을 인정하는 것이 유토피아를 SF의 중요한 소재로 받아들이는 판단을 뒷받침한다."
    },
    {
      "id": "R34",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "인류가 심각한 위기에 처했다는 현실을 근거로 이상 세계를 탐색하는 SF의 역할이 더욱 중요하다는 주장을 세운다."
    },
    {
      "id": "R35",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "SF가 현실을 비판적으로 성찰하게 한다는 논의에서 현실 너머의 이상 세계를 탐색하는 역할로 논의를 확장한다."
    }
  ]
}

